// OFFLINE TEMPLATE - no AI, no API key. Deterministic, so the demo and the tests
// always produce the same drafts. Set LLM_PROVIDER to use a real model instead.
const s = $('Settings').first().json;
const a = $json;
const first = String(a.contact_name || '').split(' ')[0] || 'there';
const hints = {
  'Restaurant': 'take-out containers, napkins and cleaning supplies',
  'Cafe & bakery': 'cups, lids and bakery boxes',
  'Healthcare office': 'gloves, wipes and paper goods',
  'Property management': 'trash liners, paper towels and floor care',
  'Gym & fitness': 'paper towels, sanitizer and trash liners',
};
let subject, body;
if (a.kind === 'reconnect') {
  const last = new Date(a.last_order_date).toLocaleDateString('en-US', { month: 'long', day: 'numeric', timeZone: 'UTC' });
  subject = 'Checking in on your ' + a.last_product + ' order';
  body = [
    'Hi ' + first + ',',
    '',
    'Your last order with us was on ' + last + ', so I wanted to check in. Are you still stocked up on ' + a.last_product + ', or is there anything we could do better on price, delivery days or product mix?',
    '',
    'If it helps, I can send a quick quote for your usual order, or samples of anything new you want to try.',
    '',
    'Just reply to this email and I will take care of it.',
    '',
    'Best regards,',
    a.sales_rep,
    s.companyName,
  ].join('\n');
} else {
  const hint = hints[a.segment] || 'everyday supplies';
  subject = 'Wholesale supplies for ' + a.company;
  body = [
    'Hi ' + first + ',',
    '',
    'I am ' + a.sales_rep + ' with ' + s.companyName + '. We supply ' + hint + ' to ' + String(a.segment).toLowerCase() + ' businesses around ' + a.city + ', with regular delivery days and no minimum contract.',
    '',
    'Would a short price list for the items you use most be useful? If you tell me what you order today, I can put together a side-by-side quote.',
    '',
    'Best regards,',
    a.sales_rep,
    s.companyName,
  ].join('\n');
}
return { json: { followup_id: a.followup_id, subject, body, drafted_by: 'offline template (no AI)' } };

// Builds the request for the configured AI provider. The API key is NOT read here:
// it is added as a header in the next step, so it never lands in the saved run data.
const s = $('Settings').first().json;
const a = $json;
const system = [
  'You write short, friendly B2B sales emails for ' + s.companyName + ', a wholesale distributor.',
  'Plain text, under 120 words, signed by the sales rep named in the facts.',
  'Never invent prices, discounts, deadlines or facts that are not in the input.',
  'Answer with JSON only: {"subject": "...", "body": "..."}',
].join(' ');
const facts = {
  email_type: a.kind === 'reconnect' ? 'reconnect with a customer who stopped ordering' : 'first email to a new wholesale prospect',
  company: a.company, contact_name: a.contact_name, segment: a.segment, city: a.city,
  sales_rep: a.sales_rep, last_order_date: a.last_order_date, days_since_last_order: a.days_quiet,
  last_product: a.last_product, why_this_prospect: a.fit_reason, internal_notes: a.notes,
};
const user = 'Write the email. Facts:\n' + JSON.stringify(facts, null, 2);
const p = s.llmProvider;
let url, body;
if (p === 'anthropic') {
  url = (s.llmBaseUrl || 'https://api.anthropic.com') + '/v1/messages';
  body = { model: s.llmModel || 'claude-sonnet-5', max_tokens: 4000, output_config: { effort: 'low' },
           system, messages: [{ role: 'user', content: user }] };
} else if (p === 'ollama') {
  if (!s.llmModel) throw new Error('LLM_MODEL is required for ollama');
  url = (s.llmBaseUrl || 'http://host.docker.internal:11434') + '/api/chat';
  body = { model: s.llmModel, stream: false, format: 'json',
           messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
} else if (p === 'openai') {
  if (!s.llmModel) throw new Error('LLM_MODEL is required for openai');
  url = (s.llmBaseUrl || 'https://api.openai.com/v1') + '/chat/completions';
  body = { model: s.llmModel, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
} else {
  throw new Error('Unknown LLM_PROVIDER "' + p + '". Use stub, openai, anthropic or ollama.');
}
return { json: { followup_id: a.followup_id, company: a.company, llm: { provider: p, url, body } } };

// Reads the AI answer for any supported provider and checks it is usable.
const req = $('Build AI request').item.json;
const r = $json;
let text = '';
if (req.llm.provider === 'anthropic') {
  if (r.stop_reason === 'refusal') throw new Error('The model declined to write this email');
  text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
} else if (req.llm.provider === 'ollama') {
  text = (r.message && r.message.content) || '';
} else {
  text = (((r.choices || [])[0] || {}).message || {}).content || '';
}
const start = text.indexOf('{'), end = text.lastIndexOf('}');
if (start < 0 || end < start) throw new Error('The AI reply had no JSON: ' + text.slice(0, 200));
const out = JSON.parse(text.slice(start, end + 1));
if (!out.subject || !out.body) throw new Error('The AI reply is missing subject or body');
return { json: { followup_id: req.followup_id, subject: String(out.subject).trim(), body: String(out.body).trim(),
                 drafted_by: req.llm.provider + ':' + (req.llm.body.model || '') } };

const s = $('Settings').first().json;
const found = $('Find quiet customers and new prospects').all().map(i => i.json);
const saved = new Set($input.all().map(i => i.json.followup_id));
const rows = found.filter(f => saved.has(f.followup_id));
if (rows.length === 0) return [];
const link = s.baseUrl + '/webhook/approvals';
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const label = k => k === 'reconnect' ? 'Win back (no recent orders)' : 'New prospect';
const list = rows.map(r => '- ' + r.company + ' (' + label(r.kind) + ', rep: ' + r.sales_rep + ')').join('\n');
const text = [
  'Good morning,', '',
  rows.length + ' follow-up email(s) are drafted and waiting for your approval. Nothing has been sent.', '',
  list, '',
  'Review, edit, approve or reject them here: ' + link,
].join('\n');
const html = '<p>Good morning,</p><p><b>' + rows.length + ' follow-up email(s)</b> are drafted and waiting for your approval. Nothing has been sent.</p><ul>'
  + rows.map(r => '<li><b>' + esc(r.company) + '</b> - ' + esc(label(r.kind)) + ', rep: ' + esc(r.sales_rep) + '</li>').join('')
  + '</ul><p><a href="' + esc(link) + '" style="background:#1f6f43;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none">Open the approval queue</a></p>';
return [{ json: { to: s.managerEmail, subject: rows.length + ' sales follow-up(s) waiting for your approval', text, html, count: rows.length } }];

const req = $('Build AI request').item.json;
const e = $json.error;
const msg = (e && (e.message || e.description)) || (typeof e === 'string' ? e : JSON.stringify($json).slice(0, 300));
return { json: { followup_id: req.followup_id, company: req.company, error: 'AI draft failed: ' + msg } };
